<main class="main student-status-page"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><a href="<?= url('/admin/students') ?>">Students</a><i data-lucide="chevron-right"></i><span>Status</span></nav><h1>Active / Inactive Students</h1><p>Control which students appear in attendance and live dashboard totals.</p></div></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label for="status-search">Search students</label><input class="module-input" id="status-search" name="search" value="<?= e($search) ?>" placeholder="Name or registration"></div><div></div><button class="btn btn--secondary">Search</button></form><form method="post" action="<?= url('/admin/students/status') ?>"><?= csrf_field() ?><section class="module-card"><header class="module-card__header"><div><h2>Student Status</h2><p>Select students, then apply their new status.</p></div><div class="filter-actions"><button class="btn btn--secondary" name="status" value="inactive"><i data-lucide="user-x"></i>Set Inactive</button><button class="btn btn--primary" name="status" value="active"><i data-lucide="user-check"></i>Set Active</button></div></header><div class="module-card__body"><?php if(!$students):?><div class="compact-empty"><h3>No students found</h3></div><?php else:?><label class="check-row"><input type="checkbox" onclick="document.querySelectorAll('[name=\'student_ids[]\']').forEach(x=>x.checked=this.checked)"> Select all students</label><div class="table-scroll"><table class="data-table"><thead><tr><th>Select</th><th>Student</th><th>Registration</th><th>Class</th><th>Current status</th></tr></thead><tbody><?php foreach($students as$s):?><tr><td><input type="checkbox" name="student_ids[]" value="<?= e($s['id']) ?>" aria-label="Select <?= e($s['student_name']) ?>"></td><td><?= e($s['student_name']) ?></td><td><?= e($s['registration_no']) ?></td><td><?= e($s['class_name']) ?></td><td><span class="student-status student-status--<?= e($s['status']) ?>"><?= e(ucfirst($s['status'])) ?></span></td></tr><?php endforeach?></tbody></table></div><?php endif?></div></section></form></div></div></main>
